def expression(text):
    # Tokenize
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            num = int(text[i:j])
            tokens.append(num)
            i = j
        elif ch in '+-*()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError("Invalid character")
    # Parsing functions
    pos = 0
    def parse_expression():
        nonlocal pos
        left = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                left += right
            else:
                left -= right
        return left
    def parse_term():
        nonlocal pos
        left = parse_factor()
        while pos < len(tokens) and tokens[pos] == '*':
            pos += 1
            right = parse_factor()
            left *= right
        return left
    def parse_factor():
        nonlocal pos
        # Unary plus/minus
        if pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            val = parse_factor()
            if op == '+':
                return val
            else:
                return -val
        # Parentheses
        if pos < len(tokens) and tokens[pos] == '(':
            pos += 1
            val = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return val
        # Number
        if pos < len(tokens) and isinstance(tokens[pos], int):
            val = tokens[pos]
            pos += 1
            return val
        raise ValueError("Invalid syntax")
    try:
        result = parse_expression()
        if pos != len(tokens):
            raise ValueError("Invalid syntax")
        return result
    except ValueError:
        raise

